@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;


@layer nz.components {
  .nz-input.nz-number-field {
    --_nz-number-field-button: var(--nz-size-control-md);

    &[data-size='sm'] {
      --_nz-number-field-button: var(--nz-size-control-sm);
    }

    &[data-size='lg'] {
      --_nz-number-field-button: var(--nz-size-control-lg);
    }

    /* the buttons' hover fill stays inside the rounded corners */
    &:has(> .nz-number-field-button) {
      gap: 0;
      padding-inline: 0;
      overflow: clip;
    }
  }

  .nz-number-field-input {
    font-variant-numeric: tabular-nums;

    .nz-number-field:has(> .nz-number-field-button) > & {
      text-align: center;
    }
  }

  .nz-number-field-button {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--_nz-number-field-button);
    block-size: 100%;
    padding: 0;
    border: 0;
    background: transparent;
    color: var(--nz-number-field-button-fg, var(--nz-icon-primary));
    font-size: var(--nz-size-icon-sm);
    cursor: pointer;
    transition: background-color var(--nz-duration-fast) var(--nz-easing-standard);

    @media (hover: hover) {
      &:hover:not(:disabled) {
        background: var(--nz-bg-hover);
      }
    }

    &[data-pressed]:not(:disabled) {
      background: var(--nz-bg-pressed);
    }

    &:disabled {
      color: var(--nz-text-disabled);
      cursor: not-allowed;
    }
  }

  .nz-number-field-icon {
    display: inline-flex;
  }

  @media (forced-colors: active) {
    .nz-number-field-button {
      color: ButtonText;
    }

    .nz-number-field-button:disabled {
      color: GrayText;
    }
  }
}
